def init_thai_font():
    # ตรวจสอบไฟล์ในโฟลเดอร์ปัจจุบันก่อน
    font_path = "Sarabun-Regular.ttf"
    font_bold_path = font_path

    if os.path.exists(font_path):
        try:
            pdfmetrics.registerFont(TTFont('ThaiFont', font_path))
            if os.path.exists(font_bold_path):
                pdfmetrics.registerFont(TTFont('ThaiFont-Bold', font_bold_path))
                from reportlab.pdfbase.pdfmetrics import registerFontFamily
                registerFontFamily('ThaiFont', normal='ThaiFont', bold='ThaiFont-Bold')
            return 'ThaiFont'
        except Exception as e:
            print(f"Error loading font: {e}")

    # กรณีหาไม่เจอ ให้ใช้ฟอนต์ลินุกซ์มาตรฐานที่ไม่ใช้ PUA
    fallback_linux = "/usr/share/fonts/truetype/tlwg/Loma.ttf"
    if os.path.exists(fallback_linux):
        pdfmetrics.registerFont(TTFont('ThaiFont', fallback_linux))
        return 'ThaiFont'

    return 'Helvetica'

THAI_FONT = init_thai_font()
class RotatedText(Flowable):
    def __init__(self, text, font_name=THAI_FONT, font_size=8):
        Flowable.__init__(self)
        self.text = text
        self.font_name = font_name
        self.font_size = font_size
        self.text_w = stringWidth(text, font_name, font_size)
        # ตั้งค่าขนาดช่อง: กว้างพอดีฟอนต์, สูงให้พอดีความยาวข้อความ
        self.width = font_size + 2
        self.height = self.text_w + 10

    def draw(self):
        self.canv.saveState()
        self.canv.setFont(self.font_name, self.font_size)
        self.canv.translate(self.width / 2.0, 5)
        self.canv.rotate(90)  # หมุน 90 องศา (ตั้งฉาก อ่านจากล่างขึ้นบน)
        self.canv.drawString(0, -self.font_size / 3.0, self.text)
        self.canv.restoreState()

    @staticmethod
    def adjust_thai_text(text):
        if not text:
            return ""

        # ชุดสระบน และวรรณยุกต์
        upper_vowels = {'\u0e31', '\u0e34', '\u0e35', '\u0e36', '\u0e37', '\u0e4d', '\u0e47'}
        tall_consonants = {'ป', 'ฝ', 'ฟ', 'ฬ'}
        tones = {'\u0e48', '\u0e49', '\u0e4a', '\u0e4b', '\u0e4c'}

        # รหัส PUA ฟอนต์ TH Sarabun New
        tone_high = {
            '\u0e48': '\uf70a', '\u0e49': '\uf70b', '\u0e4a': '\uf70c', '\u0e4b': '\uf70d', '\u0e4c': '\uf70e'
        }
        tone_left = {
            '\u0e48': '\uf713', '\u0e49': '\uf714', '\u0e4a': '\uf715', '\u0e4b': '\uf716', '\u0e4c': '\uf717'
        }
        tone_high_left = {
            '\u0e48': '\uf705', '\u0e49': '\uf706', '\u0e4a': '\uf707', '\u0e4b': '\uf708', '\u0e4c': '\uf709'
        }

        # ตัดเชิง ญ/ฐ เมื่อมีสระล่าง
        lower_vowels = {'\u0e38', '\u0e39', '\u0e3a'}
        special_bases = {'ญ': '\uf70f', 'ฐ': '\uf700'}

        chars = list(text)
        result = []
        n = len(chars)

        for i, ch in enumerate(chars):
            p1 = chars[i - 1] if i > 0 else ''
            p2 = chars[i - 2] if i > 1 else ''
            next_ch = chars[i + 1] if i + 1 < n else ''

            # จัดการ ฐ/ญ ตัดเชิงเมื่อมีสระอุ/สระอู
            if ch in special_bases and next_ch in lower_vowels:
                result.append(special_bases[ch])
                continue

            # จัดการวรรณยุกต์ลอย
            if ch in tones:
                if p1 in upper_vowels and p2 in tall_consonants:
                    result.append(tone_high_left.get(ch, ch))
                elif p1 in upper_vowels:
                    result.append(tone_high.get(ch, ch))
                elif p1 in tall_consonants:
                    result.append(tone_left.get(ch, ch))
                else:
                    result.append(ch)
            else:
                result.append(ch)

        return "".join(result)


