def calc_grade(total):
    if total >= 80: return "4"
    elif total >= 75: return "3.5"
    elif total >= 70: return "3"
    elif total >= 65: return "2.5"
    elif total >= 60: return "2"
    elif total >= 55: return "1.5"
    elif total >= 50: return "1"
    return "0"

def get_term_att(cur, sno, term):
    cur.execute("SELECT status, COUNT(*) FROM attendance_daily WHERE seat_no=? AND term=? AND status != '' GROUP BY status", (sno, term))
    stats = {r[0]: r[1] for r in cur.fetchall()}
    present = stats.get('ม', 0)
    sick = stats.get('ป', 0)
    leave = stats.get('ล', 0)
    absent = stats.get('ข', 0)
    tot_open = present + sick + leave + absent
    return tot_open, present, sick, leave, absent

def get_indicator_counts(subject_key, grade_str):
    g_str = ''.join(filter(str.isdigit, grade_str.replace('๑','1').replace('๒','2').replace('๓','3').replace('๔','4').replace('๕','5').replace('๖','6')))
    g = int(g_str) if g_str else 1
    counts = {
        ("thai", 1): [22, 13, 9], ("thai", 2): [27, 18, 9], ("thai", 3): [31, 23, 8],
        ("thai", 4): [33, 26, 7], ("thai", 5): [33, 24, 9], ("thai", 6): [34, 22, 12],
        ("math", 1): [10, 3, 7], ("math", 2): [16, 8, 8], ("math", 3): [28, 15, 13],
        ("math", 4): [22, 12, 10], ("math", 5): [19, 9, 10], ("math", 6): [21, 8, 13],
        ("sci", 2): [16, 8, 8], ("soc", 2): [28, 18, 10], ("his", 2): [6, 4, 2],
        ("health", 2): [21, 15, 6], ("art", 2): [25, 16, 9], ("career", 2): [3, 2, 1],
        ("eng", 2): [16, 10, 6], ("eng_extra", 2): [10, 7, 3], ("anti_corrupt", 2): [9, 6, 3]
    }
    return counts.get((subject_key, g), [20, 14, 6])
