        ("ว 2.1 ป.1/1", "อธิบายสมบัติที่สังเกตได้ของวัสดุที่ใช้ทำวัตถุซึ่งทำจากวัสดุชนิดเดียวหรือหลายชนิดประกอบกันโดยใช้หลักฐานเชิงประจักษ์", "ระหว่างทาง"),
        ("ว 2.1 ป.1/2", "ระบุชนิดของวัสดุและจัดกลุ่มวัสดุตามสมบัติที่สังเกตได้", "ปลายทาง"),
        ("ว 2.3 ป.1/1", "บรรยายการเกิดเสียงและทิศทางการเคลื่อนที่ของเสียงจากหลักฐานเชิงประจักษ์", "ปลายทาง"),
        ("ว 3.1 ป.1/1", "ระบุดาวที่ปรากฏบนท้องฟ้าในเวลากลางวันและกลางคืน จากข้อมูลที่รวบรวมได้", "ระหว่างทาง"),
        ("ว 3.1 ป.1/2", "อธิบายสาเหตุที่มองไม่เห็นดาวส่วนใหญ่ในเวลากลางวันจากหลักฐานเชิงประจักษ์", "ปลายทาง"),
        ("ว 3.2 ป.1/1", "อธิบายลักษณะภายนอกของหินจากลักษณะเฉพาะตัวที่สังเกตได้", "ปลายทาง"),
        ("ว 4.2 ป.1/1", "แก้ปัญหาอย่างง่ายโดยใช้การลองผิดลองถูก การเปรียบเทียบ", "ระหว่างทาง"),
        ("ว 4.2 ป.1/2", "แสดงลำดับขั้นตอนการทำงานหรือการแก้ปัญหาอย่างง่ายโดยใช้ภาพ สัญลักษณ์ หรือข้อความ", "ระหว่างทาง"),
