        ("ว 1.2 ป.2/2", "ตระหนักถึงความจำเป็นที่พืชต้องได้รับน้ำและแสงเพื่อการเจริญเติบโต โดยดูแลพืชให้ได้รับสิ่งดังกล่าวอย่างเหมาะสม", "ระหว่างทาง"),
