        ("ว 2.1 ป.2/1", "เปรียบเทียบสมบัติการดูดซับน้ำของวัสดุโดยใช้หลักฐานเชิงประจักษ์ และระบุการนำสมบัติการดูดซับน้ำของวัสดุไปประยุกต์ใช้ในการทำวัตถุในชีวิตประจำวัน", "ระหว่างทาง"),
