        ("ว 2.1 ป.2/3", "เปรียบเทียบสมบัติที่สังเกตได้ของวัสดุ เพื่อนำมาทำเป็นวัตถุในการใช้งานตามวัตถุประสงค์และอธิบายการนำวัสดุที่ใช้แล้วกลับมาใช้ใหม่โดยใช้หลักฐานเชิงประจักษ์", "ระหว่างทาง"),
        ("ว 2.1 ป.2/4", "ตระหนักถึงประโยชน์ของการนำวัสดุที่ใช้แล้วกลับมาใช้ใหม่ โดยการนำวัสดุที่ใช้แล้วกลับมาใช้ใหม่", "ปลายทาง"),
        ("ว 2.3 ป.2/1", "บรรยายแนวการเคลื่อนที่ของแสงจากแหล่งกำเนิดแสง และอธิบายการมองเห็นวัตถุจากหลักฐานเชิงประจักษ์", "ระหว่างทาง"),
        ("ว 2.3 ป.2/2", "ตระหนักในคุณค่าของความรู้ของการมองเห็นโดยเสนอแนะแนวทางการป้องกันอันตรายจากการมองวัตถุที่อยู่ในบริเวณที่มีแสงสว่างไม่เหมาะสม", "ปลายทาง"),
        ("ว 3.2 ป.2/1", "ระบุส่วนประกอบของดิน และจำแนกชนิดของดินโดยใช้ลักษณะเนื้อดินและการจับตัวเป็นเกณฑ์", "ระหว่างทาง"),
        ("ว 3.2 ป.2/2", "อธิบายการใช้ประโยชน์จากดิน จากข้อมูลที่รวบรวมได้", "ปลายทาง"),
        ("ว 4.2 ป.2/1", "แสดงลำดับขั้นตอนการทำงานหรือการแก้ปัญหาอย่างง่ายโดยใช้ภาพ สัญลักษณ์ หรือข้อความ", "ระหว่างทาง"),
