        ("ว 2.1 ป.3/2", "อธิบายการเปลี่ยนแปลงของวัสดุเมื่อทำให้ร้อนขึ้นหรือทำให้เย็นลง โดยใช้หลักฐานเชิงประจักษ์", "ปลายทาง"),
