        ("ว 2.2 ป.3/2", "เปรียบเทียบและยกตัวอย่างแรงสัมผัสและแรงไม่สัมผัสที่มีผลต่อการเคลื่อนที่ของวัตถุโดยใช้หลักฐานเชิงประจักษ์", "ปลายทาง"),
        ("ว 2.2 ป.3/3", "จำแนกวัตถุโดยใช้การดึงดูดกับแม่เหล็กเป็นเกณฑ์จากหลักฐานเชิงประจักษ์", "ระหว่างทาง"),
        ("ว 2.2 ป.3/4", "ระบุขั้วแม่เหล็กและพยากรณ์ผลที่เกิดขึ้นระหว่างขั้วแม่เหล็กเมื่อนำมาเข้าใกล้กันจากหลักฐานเชิงประจักษ์", "ปลายทาง"),
        ("ว 2.3 ป.3/1", "ยกตัวอย่างการเปลี่ยนพลังงานหนึ่งไปเป็นอีกพลังงานหนึ่งจากหลักฐานเชิงประจักษ์", "ระหว่างทาง"),
        ("ว 2.3 ป.3/2", "บรรยายการทำงานของเครื่องกำเนิดไฟฟ้าและระบุแหล่งพลังงานในการผลิตไฟฟ้าจากข้อมูลที่รวบรวมได้", "ปลายทาง"),
        ("ว 2.3 ป.3/3", "ตระหนักในประโยชน์และโทษของไฟฟ้าโดยนำเสนอวิธีการใช้ไฟฟ้าอย่างประหยัด และปลอดภัย", "ปลายทาง"),
        ("ว 3.1 ป.3/1", "อธิบายแบบรูปเส้นทางการขึ้นและตกของดวงอาทิตย์โดยใช้หลักฐานเชิงประจักษ์", "ระหว่างทาง"),
        ("ว 3.1 ป.3/2", "อธิบายสาเหตุการเกิดปรากฏการณ์การขึ้นและตกของดวงอาทิตย์ การเกิดกลางวันกลางคืนและการกำหนดทิศ โดยใช้แบบจำลอง", "ปลายทาง"),
        ("ว 3.1 ป.3/3", "ตระหนักถึงความสำคัญของดวงอาทิตย์ โดยบรรยายประโยชน์ของดวงอาทิตย์ต่อสิ่งมีชีวิต", "ปลายทาง"),
        ("ว 3.2 ป.3/1", "ระบุส่วนประกอบของอากาศ บรรยายความสำคัญของอากาศ และผลกระทบของมลพิษทางอากาศต่อสิ่งมีชีวิต จากข้อมูลที่รวบรวมได้", "ระหว่างทาง"),
