        ("ว 4.2 ป.3/2", "เขียนโปรแกรมอย่างง่าย โดยใช้ซอฟต์แวร์หรือสื่อ และตรวจหาข้อผิดพลาดของโปรแกรม", "ระหว่างทาง"),
        ("ว 4.2 ป.3/3", "ใช้อินเทอร์เน็ตค้นหาความรู้", "ระหว่างทาง"),
