        ("ส 1.1 ป.4/4", "แสดงความเคารพพระรัตนตรัย ปฏิบัติตามไตรสิกขาและหลักธรรม โอวาท 3 ในพระพุทธศาสนาหรือหลักธรรมของศาสนาที่ตนนับถือตามที่กำหนด", "ปลายทาง"),
        ("ส 1.1 ป.4/5", "ชื่นชมการทำความดีของตนเอง บุคคลในครอบครัว โรงเรียนและชุมชนตามหลักศาสนา พร้อมทั้งบอกแนวปฏิบัติในการดำเนินชีวิต", "ปลายทาง"),
        ("ส 1.1 ป.4/6", "เห็นคุณค่าและสวดมนต์ แผ่เมตตา มีสติที่เป็นพื้นฐานของสมาธิในพระพุทธศาสนาหรือการพัฒนาจิตตามแนวทางของศาสนาที่ตนนับถือตามที่กำหนด", "ระหว่างทาง"),
        ("ส 1.1 ป.4/7", "ปฏิบัติตนตามหลักธรรมของศาสนาที่ตนนับถือ เพื่อการอยู่ร่วมกันเป็นชาติได้อย่างสมานฉันท์", "ระหว่างทาง"),
        ("ส 1.1 ป.4/8", "อธิบายประวัติศาสดาของศาสนาอื่น ๆ โดยสังเขป", "ระหว่างทาง"),
        ("ส 1.2 ป.4/1", "อภิปรายความสำคัญและมีส่วนร่วมในการบำรุงรักษาศาสนสถานของศาสนาที่ตนนับถือ", "ระหว่างทาง"),
        ("ส 1.2 ป.4/2", "มีมรรยาทของความเป็นศาสนิกชนที่ดีตามที่กำหนด", "ระหว่างทาง"),
        ("ส 1.2 ป.4/3", "ปฏิบัติตนในศาสนพิธี พิธีกรรมและวันสำคัญทางศาสนาตามที่กำหนดได้ถูกต้อง", "ปลายทาง"),
        ("ส 2.1 ป.4/1", "ปฏิบัติตนเป็นพลเมืองดีตามวิถีประชาธิปไตยในฐานะสมาชิกที่ดีของชุมชน", "ระหว่างทาง"),
        ("ส 2.1 ป.4/2", "ปฏิบัติตนในการเป็นผู้นำและผู้ตามที่ดีในชีวิตประจำวัน", "ระหว่างทาง"),
        ("ส 2.1 ป.4/3", "วิเคราะห์สิทธิพื้นฐานที่เด็กทุกคนพึงได้รับตามกฎหมาย", "ระหว่างทาง"),
        ("ส 2.1 ป.4/4", "อธิบายความแตกต่างทางวัฒนธรรมของกลุ่มคนในท้องถิ่น", "ระหว่างทาง"),
        ("ส 2.1 ป.4/5", "เสนอวิธีการที่จะอยู่ร่วมกัน อย่างสันติสุข", "ปลายทาง"),
        ("ส 2.2 ป.4/1", "อธิบายอำนาจอธิปไตยและความสำคัญของระบอบประชาธิปไตย", "ปลายทาง"),
        ("ส 2.2 ป.4/2", "อธิบายบทบาทหน้าที่ของพลเมืองในกระบวนการเลือกตั้ง", "ระหว่างทาง"),
        ("ส 2.2 ป.4/3", "อธิบายความสำคัญของสถาบันพระมหากษัตริย์ตามระบอบประชาธิปไตยอันมีพระมหากษัตริย์ทรงเป็นประมุข", "ระหว่างทาง"),
        ("ส 3.1 ป.4/1", "ระบุปัจจัยที่มีผลต่อการเลือกซื้อสินค้าและบริการ", "ระหว่างทาง"),
        ("ส 3.1 ป.4/2", "บอกสิทธิพื้นฐานและรักษาผลประโยชน์ของตนเองในฐานะผู้บริโภค", "ระหว่างทาง"),
        ("ส 3.1 ป.4/3", "อธิบายหลักการของเศรษฐกิจพอเพียงและนำไปใช้ในชีวิตประจำวันของตนเอง", "ปลายทาง"),
        ("ส 3.2 ป.4/1", "อธิบายความสัมพันธ์ทางเศรษฐกิจของคนในชุมชน", "ปลายทาง"),
        ("ส 3.2 ป.4/2", "อธิบายหน้าที่เบื้องต้นของเงิน", "ระหว่างทาง"),
        ("ส 5.1 ป.4/1", "สืบค้นและอธิบายข้อมูลลักษณะทางกายภาพในจังหวัดของตนด้วยแผนที่และรูปถ่าย", "ระหว่างทาง"),
        ("ส 5.1 ป.4/2", "ระบุแหล่งทรัพยากรและสถานที่สำคัญในจังหวัดของตนด้วยแผนที่และรูปถ่าย", "ระหว่างทาง"),
        ("ส 5.1 ป.4/3", "อธิบายลักษณะทางกายภาพที่ส่งผลต่อแหล่งทรัพยากรและสถานที่สำคัญในจังหวัด", "ระหว่างทาง"),
        ("ส 5.2 ป.4/1", "วิเคราะห์สิ่งแวดล้อมทางกายภาพที่ส่งผลต่อการดำเนินชีวิตของคนในจังหวัด", "ปลายทาง"),
        ("ส 5.2 ป.4/2", "อธิบายการเปลี่ยนแปลงสิ่งแวดล้อมในจังหวัดและผลที่เกิดจากการเปลี่ยนแปลง", "ระหว่างทาง"),
        ("ส 5.2 ป.4/3", "นำเสนอแนวทางการจัดการสิ่งแวดล้อมในจังหวัด", "ปลายทาง")
