        ("ส 1.1 ป.5/5", "แสดงความเคารพพระรัตนตรัย และปฏิบัติตามไตรสิกขา และหลักธรรมโอวาท 3 ในพระพุทธศาสนา หรือหลักธรรมของศาสนาที่ตนนับถือตามที่กำหนด", "ปลายทาง"),
