        ("ส 1.1 ป.5/7", "ปฏิบัติตนตามหลักธรรมของศาสนาที่ตนนับถือ เพื่อการพัฒนาตนเองและสิ่งแวดล้อม", "ปลายทาง"),
        ("ส 1.2 ป.5/1", "จัดพิธีกรรมตามศาสนาที่ตนนับถืออย่างเรียบง่าย มีประโยชน์ และปฏิบัติตนถูกต้อง", "ระหว่างทาง"),
        ("ส 1.2 ป.5/2", "ปฏิบัติตนในศาสนพิธี พิธีกรรม และวันสำคัญทางศาสนาตามที่กำหนด และอภิปรายประโยชน์ที่ได้รับจากการเข้าร่วมกิจกรรม", "ปลายทาง"),
