        ("ส 2.2 ป.5/3", "วิเคราะห์ประโยชน์ที่ชุมชน จะได้รับจากองค์กรปกครองส่วนท้องถิ่น", "ปลายทาง"),
        ("ส 3.1 ป.5/1", "อธิบายปัจจัยการผลิตสินค้าและบริการ", "ระหว่างทาง"),
        ("ส 3.1 ป.5/2", "ประยุกต์ใช้แนวคิดของปรัชญาของเศรษฐกิจพอเพียงในการทำกิจกรรมต่าง ๆ ในครอบครัว โรงเรียน และชุมชน", "ปลายทาง"),
