        ("ส 4.1 ป.2/2", "ลำดับเหตุการณ์ที่เกิดขึ้นในครอบครัว หรือในชีวิตของตนเองโดยใช้หลักฐานที่เกี่ยวข้อง", "ระหว่างทาง"),
        ("ส 4.2 ป.2/1", "สืบค้นถึงการเปลี่ยนแปลงในวิถีชีวิตประจำวันของคนในชุมชนของตนจากอดีตถึงปัจจุบัน", "ระหว่างทาง"),
        ("ส 4.2 ป.2/2", "อธิบายผลกระทบของการเปลี่ยนแปลงที่มีต่อวิถีชีวิตของคนในชุมชน", "ปลายทาง"),
        ("ส 4.3 ป.2/1", "ระบุบุคคลที่ทำประโยชน์ต่อท้องถิ่น หรือประเทศชาติ", "ระหว่างทาง"),
        ("ส 4.3 ป.2/2", "ยกตัวอย่างวัฒนธรรม ประเพณี และภูมิปัญญาไทยที่ภาคภูมิใจและควรอนุรักษ์ไว้", "ปลายทาง")
