        ("ส 4.1 ป.4/2", "อธิบายยุคสมัยในการศึกษาประวัติของมนุษยชาติโดยสังเขป", "ระหว่างทาง"),
        ("ส 4.1 ป.4/3", "แยกแยะประเภทหลักฐานที่ใช้ในการศึกษาความเป็นมา ของท้องถิ่น", "ระหว่างทาง"),
        ("ส 4.2 ป.4/1", "อธิบายการตั้งหลักแหล่งและพัฒนาการของมนุษย์ยุคก่อนประวัติศาสตร์และยุคประวัติศาสตร์ โดยสังเขป", "ปลายทาง"),
        ("ส 4.2 ป.4/2", "ยกตัวอย่างหลักฐานทางประวัติศาสตร์ที่พบในท้องถิ่นที่แสดงพัฒนาการของมนุษยชาติ", "ระหว่างทาง"),
        ("ส 4.3 ป.4/1", "อธิบายพัฒนาการของอาณาจักรสุโขทัยโดยสังเขป", "ปลายทาง"),
        ("ส 4.3 ป.4/2", "บอกประวัติและผลงานของบุคคลสำคัญสมัยสุโขทัย", "ระหว่างทาง"),
