        ("ศ 2.1 ป.3/1", "ระบุรูปร่างลักษณะของเครื่องดนตรี ที่เห็นและได้ยินในชีวิตประจำวัน", "ระหว่างทาง"),
        ("ศ 2.1 ป.3/2", "ใช้รูปภาพหรือสัญลักษณ์แทนเสียง และจังหวะเคาะ", "ระหว่างทาง"),
