        ("ศ 2.2 ป.3/2", "ระบุความสำคัญและประโยชน์ ของดนตรีต่อการดำเนินชีวิตของคนในท้องถิ่น", "ปลายทาง"),
        ("ศ 3.1 ป.3/1", "สร้างสรรค์การเคลื่อนไหว ในรูปแบบต่าง ๆ ในสถานการณ์สั้น ๆ", "ระหว่างทาง"),
