        ("ศ 1.1 ป.4/9", "เลือกใช้วรรณะสีเพื่อถ่ายทอดอารมณ์ ความรู้สึกในการสร้างงานทัศนศิลป์", "ระหว่างทาง"),
        ("ศ 1.2 ป.4/1", "ระบุ และอภิปรายเกี่ยวกับงานทัศนศิลป์ ในเหตุการณ์และงานเฉลิมฉลองของวัฒนธรรมในท้องถิ่น", "ปลายทาง"),
