        ("ศ 2.1 ป.4/6", "ใช้และเก็บเครื่องดนตรีอย่างถูกต้อง และปลอดภัย", "ระหว่างทาง"),
        ("ศ 2.2 ป.4/1", "บอกแหล่งที่มาและความสัมพันธ์ ของวิถีชีวิตไทยที่สะท้อนในดนตรี และเพลงท้องถิ่น", "ปลายทาง"),
