        ("ศ 3.1 ป.4/2", "ใช้ภาษาท่าและนาฏยศัพท์หรือศัพท์ทางการละครง่าย ๆ ในการถ่ายทอดเรื่องราว", "ปลายทาง"),
        ("ศ 3.1 ป.4/3", "แสดงการเคลื่อนไหวในจังหวะต่าง ๆ ตามความคิดของตน", "ระหว่างทาง"),
        ("ศ 3.1 ป.4/4", "แสดงนาฏศิลป์เป็นคู่ และหมู่", "ระหว่างทาง"),
        ("ศ 3.1 ป.4/5", "เล่าสิ่งที่ชื่นชอบในการแสดง โดยเน้นจุดสำคัญของเรื่องและลักษณะเด่น ของตัวละคร", "ระหว่างทาง"),
        ("ศ 3.2 ป.4/1", "อธิบายประวัติความเป็นมาของนาฏศิลป์ หรือชุดการแสดงอย่างง่าย ๆ", "ระหว่างทาง"),
        ("ศ 3.2 ป.4/2", "เปรียบเทียบการแสดงนาฏศิลป์กับการแสดงที่มาจากวัฒนธรรมอื่น", "ปลายทาง"),
        ("ศ 3.2 ป.4/3", "อธิบายความสำคัญของการแสดงความเคารพในการเรียนและการแสดงนาฏศิลป์", "ระหว่างทาง"),
