# 2. แก้ไขฟังก์ชัน get_real_indicators เดิม ให้ใช้ข้อมูลจาก INDICATORS_DB
def get_real_indicators(subject_key, grade_str):
    g_str = ''.join(filter(str.isdigit, grade_str.replace('๑','1').replace('๒','2').replace('๓','3').replace('๔','4').replace('๕','5').replace('๖','6')))
    g = int(g_str) if g_str else 1

    # ลองดึงข้อมูลตัวชี้วัดจริงจาก INDICATORS_DB ก่อน
    real_data = INDICATORS_DB.get((subject_key, g))
    if real_data:
        return real_data

    # ถ้าวิชาหรือชั้นนั้นยังไม่ได้เพิ่มใน INDICATORS_DB ให้ใช้ข้อความจำลอง (Fallback) แบบเดิม
    tot, form, _ = get_indicator_counts(subject_key, grade_str)
    prefix_map = {"thai":"ท", "math":"ค", "sci":"ว", "soc":"ส", "his":"ส", "health":"พ", "art":"ศ", "career":"ง", "eng":"อ", "eng_extra":"อ", "anti_corrupt":"ส"}
    prefix = prefix_map.get(subject_key, "รหัส")
    results = []
    for i in range(1, tot + 1):
        itype = "ระหว่างทาง" if i <= form else "ปลายทาง"
        results.append((f"{prefix}.{i}", f"ตัวชี้วัดที่ {i} ตามหลักสูตรสถานศึกษา", itype))
    return results

def get_style():
    return TableStyle([
        ('GRID', (0,0), (-1,-1), 0.5, colors.black),
        ('BACKGROUND', (0,0), (-1,0), colors.HexColor('#f1f5f9')),
        ('FONTNAME', (0,0), (-1,-1), THAI_FONT),
        ('FONTSIZE', (0,0), (-1,-1), 7.5),
        ('ALIGN', (0,0), (-1,-1), 'CENTER'),
        ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
        ('TOPPADDING', (0,0), (-1,-1), 5),    # เพิ่มระยะขอบบน 5 พิกเซล
        ('BOTTOMPADDING', (0,0), (-1,-1), 5)  # เพิ่มระยะขอบล่าง 5 พิกเซล
    ])

def generate_individual_report_pdf(output_pdf="ปพ.6_รายงานตัวชี้วัดรายบุคคล.pdf"):
    conn = get_connection(); cur = conn.cursor()
    cfg = dict(cur.execute("SELECT key, val FROM config").fetchall())
    students = cur.execute("SELECT seat_no, citizen_id, student_id, title, first_name, last_name FROM students ORDER BY seat_no ASC").fetchall()
    school_name, grade, year = cfg.get("school_name", "โรงเรียนสาธิต ปพ.5"), cfg.get("grade", "ป.1"), cfg.get("year", "2569")

    doc = BaseDocTemplate(output_pdf, pageTemplates=[PageTemplate(id='P', pagesize=A4, frames=[Frame(25, 25, A4[0]-50, A4[1]-50)])])
    story = []
    t_main = ParagraphStyle('TMain', fontName=THAI_FONT, fontSize=16, leading=20, alignment=1)
    t_sub_l = ParagraphStyle('TSubL', fontName=THAI_FONT, fontSize=11, leading=15, alignment=0)
    style_desc = ParagraphStyle('Desc', fontName=THAI_FONT, fontSize=9, leading=16)

    for s in students:
        sno, sid, nm = s[0], s[2], f"{s[3] or ''}{s[4] or ''} {s[5] or ''}"
        story.append(Paragraph("<b>รายงานผลการประเมินตัวชี้วัดผู้เรียนรายบุคคล (ปพ.6)</b>", t_main))
        story.append(Spacer(1, 10))
        story.append(Paragraph(f"<b>ชื่อ-สกุล:</b> {nm}     <b>เลขที่:</b> {sno}     <b>รหัสประจำตัว:</b> {sid}", t_sub_l))
        story.append(Paragraph(f"<b>ระดับชั้น:</b> {grade}     <b>ปีการศึกษา:</b> {year}     <b>สถานศึกษา:</b> {school_name}", t_sub_l))
        story.append(Spacer(1, 15))

        for sub_key, sub_th, sub_type in SUBJECT_LIST:
            inds = get_real_indicators(sub_key, grade)
            s1 = cur.execute("SELECT formative, exam FROM subject_scores WHERE seat_no=? AND subject_key=? AND term=1", (sno, sub_key)).fetchone() or (0,0)
            s2 = cur.execute("SELECT formative, exam FROM subject_scores WHERE seat_no=? AND subject_key=? AND term=2", (sno, sub_key)).fetchone() or (0,0)
            gr = calc_grade(round((sum(s1) + sum(s2)) / 2.0, 1))
            is_pass = "ผ่าน" if float(gr) >= 1.0 else "ไม่ผ่าน"

            story.append(Paragraph(f"<b>รายวิชา: {sub_th} ({sub_type})</b> - ผลการเรียน: {gr} ({is_pass})", t_sub_l))
            story.append(Spacer(1, 4))

            t_data = [["รหัสตัวชี้วัด", "รายละเอียดมาตรฐานการเรียนรู้และตัวชี้วัด", "ประเภท", "คะแนนเต็ม", "คะแนนที่ได้", "ประเมินผล"]]
            for code, desc, itype in inds:
                fixed_desc = RotatedText.adjust_thai_text(desc) # <--- เรียกใช้ฟังก์ชันตรงนี้
                t_data.append([code, Paragraph(fixed_desc, style_desc), itype, "", "", is_pass])

            t = Table(t_data, colWidths=[65, 235, 60, 50, 60, 50], repeatRows=1)
            ts = get_style(); ts.add('ALIGN', (1,1), (1,-1), 'LEFT'); ts.add('VALIGN', (0,0), (-1,-1), 'TOP')
            t.setStyle(ts); story.append(t); story.append(Spacer(1, 10))
        story.append(PageBreak())

    doc.build(story); conn.close()
    return output_pdf

def generate_pp5_pdf(output_pdf="ปพ.5_ประถม_ฉบับสมบูรณ์.pdf"):
    conn = get_connection(); cur = conn.cursor()
    cfg = dict(cur.execute("SELECT key, val FROM config").fetchall())
    students = cur.execute("SELECT seat_no, citizen_id, student_id, title, first_name, last_name FROM students ORDER BY seat_no ASC").fetchall()
    sn, g, y, t1 = cfg.get("school_name",""), cfg.get("grade","ป.1"), cfg.get("year","2569"), cfg.get("teacher_1","")

    doc = BaseDocTemplate(output_pdf, pageTemplates=[
        PageTemplate(id='P', pagesize=A4, frames=[Frame(25, 25, A4[0]-50, A4[1]-50)]),
        PageTemplate(id='L', pagesize=landscape(A4), frames=[Frame(25, 25, landscape(A4)[0]-50, landscape(A4)[1]-50)])
    ])
    story = []
    tm = ParagraphStyle('TM', fontName=THAI_FONT, fontSize=15, leading=19, alignment=1)
    ts = ParagraphStyle('TS', fontName=THAI_FONT, fontSize=11, leading=15, alignment=1)
    td = ParagraphStyle('TD', fontName=THAI_FONT, fontSize=9, leading=16)

    # 1. หน้าปก
    story.append(Paragraph("<b>สมุดบันทึกผลการพัฒนาคุณภาพผู้เรียน (ปพ.5)</b>", tm))
    story.append(Paragraph(f"<b>{sn}</b><br/>ข้อมูลสาธิต<br/>หลักสูตรสถานศึกษา พุทธศักราช ๒๕๖๘ | ระดับ {g} ปีการศึกษา {y}<br/><b>ครูประจำชั้น:</b> {t1}", ts))
    story.append(Spacer(1, 10))
    story.append(Paragraph("<b>สรุปผลสัมฤทธิ์ทางการเรียนตามหลักสูตรแกนกลางฯ (ฉบับปรับปรุง 2560)</b>", ts))
    story.append(Spacer(1, 5))
    cd = [["กลุ่มสาระการเรียนรู้ / รายวิชา", "ประเภท", "จำนวน นร.", "4", "3.5", "3", "2.5", "2", "1.5", "1", "0", "ร", "มส"]]
    for sk, th, typ in SUBJECT_LIST:
        c = {gr: 0 for gr in ["4","3.5","3","2.5","2","1.5","1","0","ร","มส"]}
        for s in students:
            s1 = cur.execute("SELECT formative, exam FROM subject_scores WHERE seat_no=? AND subject_key=? AND term=1", (s[0], sk)).fetchone() or (0,0)
            s2 = cur.execute("SELECT formative, exam FROM subject_scores WHERE seat_no=? AND subject_key=? AND term=2", (s[0], sk)).fetchone() or (0,0)
            c[calc_grade(round((sum(s1)+sum(s2))/2.0, 1))] += 1
        cd.append([th, typ, str(len(students)), str(c['4']), str(c['3.5']), str(c['3']), str(c['2.5']), str(c['2']), str(c['1.5']), str(c['1']), str(c['0']), str(c['ร']), str(c['มส'])])
    t = Table(cd, colWidths=[150, 45, 35, 27, 27, 27, 27, 27, 27, 27, 27, 27, 27])
    t.setStyle(TableStyle([('GRID',(0,0),(-1,-1),0.5,colors.black),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#f1f5f9')),('FONTNAME',(0,0),(-1,-1),THAI_FONT),('FONTSIZE',(0,0),(-1,-1),8),('ALIGN',(0,0),(-1,-1),'CENTER'),('ALIGN',(0,1),(0,-1),'LEFT'),('VALIGN',(0,0),(-1,-1),'MIDDLE')]))
    story.append(t); story.append(Spacer(1, 15))
    story.append(Table([["ลงชื่อ.......................................................ครูประจำชั้น", "ลงชื่อ.......................................................หัวหน้างานวัดผล"], [f"({t1})", "(.......................................................)"], ["", ""], ["ลงชื่อ.......................................................รองผู้อำนวยการ", "ลงชื่อ.......................................................ผู้อำนวยการสถานศึกษา"], ["(.......................................................)", "(.......................................................)"]], colWidths=[270, 270], style=[('FONTNAME',(0,0),(-1,-1),THAI_FONT),('FONTSIZE',(0,0),(-1,-1),8.5),('ALIGN',(0,0),(-1,-1),'CENTER')]))
    story.append(PageBreak())

    # 2. ทะเบียนประวัติ
    story.append(Paragraph("<b>ทะเบียนประวัติและข้อมูลนักเรียน</b>", tm))
    story.append(Paragraph(f"{sn} | {g} | ปีการศึกษา {y}", ts))
    story.append(Spacer(1, 10))
    bd = [["เลขที่", "เลขประจำตัวประชาชน", "เลขประจำตัว", "คำนำหน้า", "ชื่อ", "นามสกุล"]]
    for s in students: bd.append([str(s[0]), str(s[1] or ""), str(s[2] or ""), str(s[3] or ""), str(s[4] or ""), str(s[5] or "")])
    story.append(Table(bd, colWidths=[35, 125, 75, 55, 125, 125], style=[('GRID',(0,0),(-1,-1),0.5,colors.black),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#f1f5f9')),('FONTNAME',(0,0),(-1,-1),THAI_FONT),('FONTSIZE',(0,0),(-1,-1),8.5),('ALIGN',(0,0),(-1,-1),'CENTER'),('ALIGN',(4,1),(5,-1),'LEFT'),('VALIGN',(0,0),(-1,-1),'MIDDLE')]))
    story.append(NextPageTemplate('L')); story.append(PageBreak())

    # 3. เวลาเรียน
    story.append(Paragraph("<b>บันทึกเวลาเรียนและสรุปวันมาเรียนตลอดปีการศึกษา (เกณฑ์เวลาเรียนไม่น้อยกว่า 80%)</b>", tm))
    story.append(Paragraph(f"{sn} | {g} | ปีการศึกษา {y}", ts))
    story.append(Spacer(1, 6))
    ad = [["เลขที่", "ชื่อ - นามสกุล", "ภาคเรียนที่ 1 (วัน)", "", "", "", "ภาคเรียนที่ 2 (วัน)", "", "", "", "สรุปทั้งปีการศึกษา", "", "", "", "ผลการประเมิน"], ["", "", "เปิด", "มา", "ลา", "ขาด", "เปิด", "มา", "ลา", "ขาด", "วันเปิด", "มาเรียน", "ขาด/ลา", "ร้อยละ", "เวลาเรียน (80%)"]]
    for s in students:
        a1t, a1p, a1s, a1l, a1a = get_term_att(cur, s[0], 1)
        a2t, a2p, a2s, a2l, a2a = get_term_att(cur, s[0], 2)
        to, tp, ta = a1t+a2t, a1p+a2p, a1s+a1l+a1a+a2s+a2l+a2a
        pct = round((tp/to*100.0), 1) if to>0 else 100.0
        ad.append([str(s[0]), f"{s[3] or ''}{s[4] or ''} {s[5] or ''}", str(a1t), str(a1p), str(a1s+a1l), str(a1a), str(a2t), str(a2p), str(a2s+a2l), str(a2a), str(to), str(tp), str(ta), f"{pct}%", "ผ่านเกณฑ์" if pct>=80.0 else "มส"])
    story.append(Table(ad, colWidths=[28, 140, 38, 38, 38, 38, 38, 38, 38, 38, 45, 45, 45, 45, 55], repeatRows=2, style=[('GRID',(0,0),(-1,-1),0.5,colors.black),('BACKGROUND',(0,0),(-1,1),colors.HexColor('#f1f5f9')),('SPAN',(0,0),(0,1)),('SPAN',(1,0),(1,1)),('SPAN',(2,0),(5,0)),('SPAN',(6,0),(9,0)),('SPAN',(10,0),(13,0)),('SPAN',(14,0),(14,1)),('FONTNAME',(0,0),(-1,-1),THAI_FONT),('FONTSIZE',(0,0),(-1,-1),8),('ALIGN',(0,0),(-1,-1),'CENTER'),('ALIGN',(1,2),(1,-1),'LEFT'),('VALIGN',(0,0),(-1,-1),'MIDDLE')]))
    story.append(PageBreak())

    # 4. ตัวชี้วัด + ตารางเมทริกซ์ + ตารางคะแนน
    for sk, th, typ in SUBJECT_LIST:
        tot_ind, form_ind, sum_ind = get_indicator_counts(sk, g)
        inds = get_real_indicators(sk, g)

        # 4.1 รายละเอียด
        # เพิ่มการนับตัวชี้วัดจากข้อมูลจริง เพื่อแก้ปัญหาหัวกระดาษแสดงยอดรวมไม่ตรงกับในตาราง
        tot_ind = len(inds)
        form_ind = sum(1 for _, _, t in inds if "ระหว่างทาง" in t)
        sum_ind = tot_ind - form_ind

        story.append(Paragraph(f"**รายละเอียดมาตรฐานการเรียนรู้และตัวชี้วัด ({typ})**", tm))
        story.append(Paragraph(f"รายวิชา: {th} | ชั้น: {g} | **ตัวชี้วัดทั้งหมด {tot_ind} ข้อ (ระหว่างทาง {form_ind} ข้อ, ปลายทาง {sum_ind} ข้อ)**", ts))
        story.append(Spacer(1, 8))
        idat = [["ลำดับ", "รหัสตัวชี้วัด", "รายละเอียดตัวชี้วัด (คำอธิบายตามหลักสูตรแกนกลาง สพฐ.)", "ประเภทการประเมิน"]]

        for i, (cd, ds, it) in enumerate(inds, 1):
            fixed_desc = RotatedText.adjust_thai_text(ds) # <--- เรียกใช้ฟังก์ชันตรงนี้
            idat.append([str(i), cd, Paragraph(fixed_desc, td), it])

        # สร้าง TableStyle แบบจัดระเบียบและเพิ่ม Padding
        ts_idat = TableStyle([
            ('GRID',(0,0),(-1,-1),0.5,colors.black),
            ('BACKGROUND',(0,0),(-1,0),colors.HexColor('#f1f5f9')),
            ('FONTNAME',(0,0),(-1,-1),THAI_FONT),
            ('FONTSIZE',(0,0),(-1,-1),9),
            ('ALIGN',(0,0),(-1,-1),'CENTER'),
            ('ALIGN',(2,1),(2,-1),'LEFT'),
            ('VALIGN',(0,0),(-1,-1),'TOP'),
            ('VALIGN',(0,0),(-1,0),'MIDDLE'),
            ('TOPPADDING', (0,0), (-1,-1), 5),     # เพิ่มระยะขอบบน 5 พิกเซล
            ('BOTTOMPADDING', (0,0), (-1,-1), 5)   # เพิ่มระยะขอบล่าง 5 พิกเซล
        ])
        story.append(Table(idat, colWidths=[40, 80, 520, 110], repeatRows=1, style=ts_idat))
        story.append(PageBreak())

       # 4.2 ตารางเมทริกซ์สรุปตัวชี้วัดทั้งห้อง
        story.append(Paragraph(f"**ตารางสรุปผลการประเมินตัวชี้วัดรายวิชา (ทั้งห้อง) - {th}**", tm))
        story.append(Paragraph(f"รายวิชา: {th} | ชั้น: {g} | สรุปผลตัวชี้วัดรายข้อของนักเรียนทุกท่าน", ts))
        story.append(Spacer(1, 8))

        ind_codes = [code for code, _, _ in inds]

        # ใช้ RotatedText ครอบรหัสตัวชี้วัด เพื่อให้มันหมุนตั้งฉาก
        mx_header = ["เลขที่", "ชื่อนักเรียน"] + [RotatedText(code) for code in ind_codes]
        mx_data = [mx_header]

        for s in students:
            nm = f"{s[3] or ''}{s[4] or ''} {s[5] or ''}"
            row = [str(s[0]), nm] + ["/" for _ in ind_codes]
            mx_data.append(row)

        col_w = [30, 130] + [max(12, 385 // max(1, len(ind_codes)))] * len(ind_codes)
        mx_tbl = Table(mx_data, colWidths=col_w, repeatRows=1)
        mx_sty = TableStyle([
            ('GRID',(0,0),(-1,-1),0.5,colors.black),
            ('BACKGROUND',(0,0),(-1,0),colors.HexColor('#f1f5f9')),
            ('FONTNAME',(0,0),(-1,-1),THAI_FONT),
            ('FONTSIZE',(0,0),(-1,-1),8),
            ('ALIGN',(0,0),(-1,-1),'CENTER'),
            ('ALIGN',(1,1),(1,-1),'LEFT'),
            ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
            ('VALIGN',(0,0),(-1,0),'BOTTOM') # บังคับให้หัวตารางชิดขอบล่าง
        ])
        mx_tbl.setStyle(mx_sty)
        story.append(mx_tbl)
        story.append(PageBreak())

        # 4.3 ตารางคะแนน
        story.append(Paragraph(f"<b>แบบบันทึกผลการประเมินผลการเรียนรู้รายวิชา ({typ})</b>", tm))
        story.append(Paragraph(f"รายวิชา: {th} | ชั้น: {g} | การประเมินผลอิงตามตัวชี้วัด", ts))
        story.append(Spacer(1, 8))
        sdat = [["เลขที่", "ชื่อ - นามสกุล", "ภาคเรียนที่ 1 (100 คะแนน)", "", "", "ภาคเรียนที่ 2 (100 คะแนน)", "", "", "สรุปผลตลอดปีการศึกษา", "", "", ""], ["", "", "ระหว่างเรียน\n(ระหว่างทาง)", "สอบ\n(ปลายทาง)", "รวม (100)", "ระหว่างเรียน\n(ระหว่างทาง)", "สอบ\n(ปลายทาง)", "รวม (100)", "รวม (200)", "คะแนนสุทธิ (100)", "ระดับผลการเรียน", "ประเมินตัวชี้วัด"]]
        for s in students:
            nm = f"{s[3] or ''}{s[4] or ''} {s[5] or ''}"
            s1 = cur.execute("SELECT formative, exam FROM subject_scores WHERE seat_no=? AND subject_key=? AND term=1", (s[0], sk)).fetchone() or (0,0)
            s2 = cur.execute("SELECT formative, exam FROM subject_scores WHERE seat_no=? AND subject_key=? AND term=2", (s[0], sk)).fetchone() or (0,0)
            net = round((sum(s1)+sum(s2))/2.0, 1); gr = calc_grade(net)
            sdat.append([str(s[0]), nm, str(int(s1[0])), str(int(s1[1])), str(int(sum(s1))), str(int(s2[0])), str(int(s2[1])), str(int(sum(s2))), str(int(sum(s1)+sum(s2))), str(net), gr, "ผ่านเกณฑ์" if float(gr)>=1.0 else "ไม่ผ่าน"])
        story.append(Table(sdat, colWidths=[25, 140, 58, 56, 48, 58, 56, 48, 50, 65, 50, 60], repeatRows=2, style=[('GRID',(0,0),(-1,-1),0.5,colors.black),('BACKGROUND',(0,0),(-1,1),colors.HexColor('#f1f5f9')),('SPAN',(0,0),(0,1)),('SPAN',(1,0),(1,1)),('SPAN',(2,0),(4,0)),('SPAN',(5,0),(7,0)),('SPAN',(8,0),(11,0)),('FONTNAME',(0,0),(-1,-1),THAI_FONT),('FONTSIZE',(0,0),(-1,-1),8),('ALIGN',(0,0),(-1,-1),'CENTER'),('ALIGN',(1,2),(1,-1),'LEFT'),('VALIGN',(0,0),(-1,-1),'MIDDLE')]))
        story.append(PageBreak())

    # 5. สรุปทุกวิชา
    story.append(Paragraph("<b>สรุปผลการประเมินทุกกลุ่มสาระการเรียนรู้ตลอดปีการศึกษา (ส่งฝ่ายวิชาการและวัดผล)</b>", tm))
    story.append(Paragraph(f"{sn} | {g} | ปีการศึกษา {y}", ts))
    story.append(Spacer(1, 6))
    ald = [["เลขที่", "รหัส", "ชื่อ - นามสกุล", "ไทย", "คณิต", "วิทย์", "สังคม", "ประวัติ", "สุขฯ", "ศิลปะ", "การงาน", "อังกฤษ", "อ.สื่อสาร", "ต้านทุจริต", "ผลการตัดสิน"]]
    for s in students:
        rw = [str(s[0]), str(s[2] or ""), f"{s[3] or ''}{s[4] or ''} {s[5] or ''}"]
        for sk, _, _ in SUBJECT_LIST:
            s1 = cur.execute("SELECT formative, exam FROM subject_scores WHERE seat_no=? AND subject_key=? AND term=1", (s[0], sk)).fetchone() or (0,0)
            s2 = cur.execute("SELECT formative, exam FROM subject_scores WHERE seat_no=? AND subject_key=? AND term=2", (s[0], sk)).fetchone() or (0,0)
            rw.append(calc_grade(round((sum(s1)+sum(s2))/2.0, 1)))
        rw.append("เลื่อนชั้น")
        ald.append(rw)
    story.append(Table(ald, colWidths=[24, 42, 135, 38, 38, 38, 38, 38, 38, 38, 38, 38, 42, 42, 45], repeatRows=1, style=[('GRID',(0,0),(-1,-1),0.5,colors.black),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#f1f5f9')),('FONTNAME',(0,0),(-1,-1),THAI_FONT),('FONTSIZE',(0,0),(-1,-1),7.5),('ALIGN',(0,0),(-1,-1),'CENTER'),('ALIGN',(2,1),(2,-1),'LEFT'),('VALIGN',(0,0),(-1,-1),'MIDDLE')]))
    story.append(PageBreak())

    # 6. กิจกรรมและคุณลักษณะ
    story.append(Paragraph("<b>สรุปผลประเมินกิจกรรมพัฒนาผู้เรียน และ คุณลักษณะอันพึงประสงค์</b>", tm))
    story.append(Paragraph(f"{sn} | {g} | ปีการศึกษา {y}", ts))
    story.append(Spacer(1, 6))
    trd = [["เลขที่", "ชื่อ - นามสกุล", "กิจกรรมพัฒนาผู้เรียน", "", "", "", "", "คุณลักษณะอันพึงประสงค์ 8 ประการ", "", "", "", "", "", "", "", "สรุปผล", "อ่าน คิดวิเคราะห์ฯ", "", "", "", "สรุปผล"], ["", "", "แนะแนว", "ลูกเสือ", "ชุมนุม", "สังคม", "สรุป", "รักชาติ", "ซื่อสัตย์", "มีวินัย", "ใฝ่รู้", "พอเพียง", "มุ่งมั่น", "รักไทย", "สาธารณะ", "", "จับใจ", "ลำดับ", "ถ่ายทอด", "รักอ่าน", ""]]
    for s in students:
        nm = f"{s[3] or ''}{s[4] or ''} {s[5] or ''}"
        av = [cur.execute("SELECT result FROM activities WHERE seat_no=? AND activity_key=? AND term=2", (s[0], k)).fetchone() for k, _ in ACTIVITY_LIST]
        avs = [r[0] if r else "ผ" for r in av]
        tr = cur.execute("SELECT t1, t2, t3, t4, t5, t6, t7, t8 FROM desired_traits WHERE seat_no=? AND term=1", (s[0],)).fetchone() or (10,)*8
        tl = "ดีเยี่ยม" if sum(tr)>=65 else ("ดี" if sum(tr)>=50 else "ผ่าน")
        rd = cur.execute("SELECT r1, r2, r3, r4 FROM reading_analysis WHERE seat_no=? AND term=1", (s[0],)).fetchone() or (25,)*4
        rl = "ดีเยี่ยม" if sum(rd)>=80 else ("ดี" if sum(rd)>=69 else "ผ่าน")
        trd.append([str(s[0]), nm] + avs + ["ผ่าน"] + [str(int(t)) for t in tr] + [tl] + [str(int(r)) for r in rd] + [rl])
    story.append(Table(trd, colWidths=[20, 105, 30, 30, 30, 30, 30, 32, 32, 32, 32, 32, 32, 32, 32, 38, 35, 35, 35, 35, 38], repeatRows=2, style=[('GRID',(0,0),(-1,-1),0.5,colors.black),('BACKGROUND',(0,0),(-1,1),colors.HexColor('#f1f5f9')),('SPAN',(0,0),(0,1)),('SPAN',(1,0),(1,1)),('SPAN',(2,0),(6,0)),('SPAN',(7,0),(14,0)),('SPAN',(15,0),(15,1)),('SPAN',(16,0),(19,0)),('SPAN',(20,0),(20,1)),('FONTNAME',(0,0),(-1,-1),THAI_FONT),('FONTSIZE',(0,0),(-1,-1),7.5),('ALIGN',(0,0),(-1,-1),'CENTER'),('ALIGN',(1,2),(1,-1),'LEFT'),('VALIGN',(0,0),(-1,-1),'MIDDLE')]))

    doc.build(story); conn.close()
    return output_pdf

def export_full_pp5(output_excel="ปพ.5_ประถม_ฉบับสมบูรณ์.xlsx", to_pdf=True):
    pdf_path = output_excel.rsplit(".", 1)[0] + ".pdf"
    generate_pp5_pdf(pdf_path)
    return output_excel, pdf_path
